import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems = {} }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);
  // --- NEW: Search State ---
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        const uid = String(decoded._id || decoded.id || decoded.userId);
        setCurrentUserId(uid);
      } catch (err) {
        console.error("Token decode failed", err);
      }
    }

    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => setItems(data))
      .catch((err) => console.error("Fetch error", err))
      .finally(() => setLoading(false));
  }, []);

  // --- UPDATED: Combined Filter Logic ---
  const filteredItems = items.filter((item) => {
    // 1. Ownership Check
    const sellerId = String(item.userId || item.user || item.sellerId || "");
    const isNotMine = !currentUserId || sellerId !== currentUserId;

    // 2. Search Check
    const matchesSearch = item.title
      .toLowerCase()
      .includes(searchTerm.toLowerCase());

    return isNotMine && matchesSearch;
  });

  if (loading) return <h1>Loading...</h1>;

  return (
    <>
      <Navbar />
      <div className="Body">
        
        {/* --- NEW: Search Bar UI --- */}
        <div style={{ padding: "20px", textAlign: "center" }}>
          <div style={{ position: "relative", display: "inline-block", width: "100%", maxWidth: "400px" }}>
            <input
              type="text"
              placeholder="Search for books..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{
                padding: "12px 40px 12px 15px",
                width: "100%",
                borderRadius: "25px",
                border: "1px solid #ddd",
                outline: "none",
                fontSize: "16px"
              }}
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm("")}
                style={{
                  position: "absolute",
                  right: "15px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "none",
                  border: "none",
                  color: "#999",
                  fontSize: "20px",
                  cursor: "pointer",
                  fontWeight: "bold",
                  marginTop: "0"
                }}
              >
                ×
              </button>
            )}
          </div>
        </div>

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px', justifyContent: 'center' }}>
          {filteredItems.length === 0 ? (
            <div className="HeadMo">
              <h1>{searchTerm ? "No matches found!" : "No books for sale!"}</h1>
            </div>
          ) : (
            filteredItems.map((item) => {
              const itemId = String(item._id || item.id);
              const isPurchased = !!purchasedItems[itemId];

              // Return the JSX (crucial for .map to work)
              return (
                <Card key={itemId} {...item}>
                  <button
                    onClick={() => !isPurchased && onBuy(item)}
                    disabled={isPurchased}
                    style={{
                      backgroundColor: isPurchased ? "#6c757d" : "#0d6efd",
                      color: "#fff",
                      borderRadius: "5px",
                      padding: "10px",
                      width: "140px",
                      border: "none",
                      cursor: isPurchased ? "not-allowed" : "pointer",
                      pointerEvents: isPurchased ? "none" : "auto", 
                      opacity: isPurchased ? 0.6 : 1,
                    }}
                  >
                    {isPurchased ? "Added to Cart" : "Add to Cart"}
                  </button>
                </Card>
              );
            })
          )}
        </div>
      </div>
      <Footer />
    </>
  );
}

export default Shop;
